<style>
:root{color-scheme:dark;--bg:#090d17;--text:#f2f5fb;--muted:#9ba6b8;--line:#ffffff1a;--accent:#83ecc4;--accent2:#91a9ff;--surface:#141b2ccc;--danger:#ff9da7}*{box-sizing:border-box}html,body{height:100%;margin:0}body{overflow:hidden;background:radial-gradient(ellipse at 5% 0,#4f74ff2e,transparent 35%),radial-gradient(ellipse at 100% 100%,#52deb81f,transparent 35%),var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif}button,input,select{font:inherit}.app{height:100dvh;padding:16px;display:grid;grid-template-columns:310px minmax(0,1fr);gap:14px}.glass{background:linear-gradient(145deg,#ffffff12,#ffffff06);border:1px solid var(--line);backdrop-filter:blur(20px);box-shadow:0 20px 70px #0005}.sidebar,.chat{min-height:0;border-radius:22px;overflow:hidden}.sidebar{display:flex;flex-direction:column}.side-head{padding:21px;border-bottom:1px solid var(--line)}.brand{display:flex;gap:10px;align-items:center;color:var(--text);text-decoration:none;font:700 1.2rem 'Space Grotesk'}.brand img{width:34px}.brand span{color:var(--accent)}.subline{color:var(--muted);margin:10px 0 16px}.search,.chat-search{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:12px;background:#080d18a8;color:var(--text);outline:none}.list-label{padding:16px 18px 8px;font-size:.68rem;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}.user-list{flex:1;overflow:auto;padding:6px 9px}.user-card{display:flex;align-items:center;gap:10px;width:100%;margin:4px 0;padding:11px;border:1px solid transparent;border-radius:14px;text-align:left;background:transparent;color:var(--text);cursor:pointer}.user-card:hover,.user-card.active{background:#ffffff0d;border-color:var(--line)}.user-card.active{box-shadow:inset 0 0 0 1px #83ecc433}.avatar-initials{width:39px;height:39px;border-radius:13px;display:grid;place-items:center;flex:none;color:#07130f;font-weight:800;background:linear-gradient(135deg,var(--accent),var(--accent2))}.contact-meta{display:grid;min-width:0;flex:1;gap:4px}.contact-meta b,.contact-meta small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.contact-meta small{font-size:.72rem;color:var(--muted)}.contact-status{font-size:.57rem;display:flex;align-items:center;gap:5px}.contact-status i{width:7px;height:7px;border-radius:50%}.unread-badge{border-radius:99px;background:var(--accent);color:#07130f;font-weight:800;padding:2px 6px}.side-foot{display:flex;gap:5px;flex-wrap:wrap;padding:12px;border-top:1px solid var(--line)}.side-link{background:transparent;color:var(--muted);border:0;padding:8px;cursor:pointer;text-decoration:none;font-size:.76rem}.side-link:hover{color:var(--text)}.abort{color:var(--danger)}.chat{display:flex;flex-direction:column;min-width:0}.chat-head{min-height:76px;display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 18px;border-bottom:1px solid var(--line)}.head-left,.head-actions{display:flex;align-items:center;gap:10px;min-width:0}.target{font:600 1rem 'Space Grotesk';white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.target-sub{font-size:.75rem;color:var(--muted);margin-top:4px}.key-input{width:140px;padding:9px;border:1px solid var(--line);border-radius:10px;background:#080d18;color:var(--text)}.icon-btn,.settings-trigger,.send,.attach,.tool-btn{border:1px solid var(--line);border-radius:11px;background:#ffffff0b;color:var(--text);padding:9px 11px;cursor:pointer}.messages{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:10px;padding:20px clamp(14px,4vw,48px)}.msg{position:relative;max-width:min(74%,650px);padding:12px 14px;border:1px solid var(--line);border-radius:17px;background:#ffffff0b;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere}.msg.sent{align-self:flex-end;background:linear-gradient(135deg,#83ecc424,#91a9ff1e);border-bottom-right-radius:4px}.msg.received{align-self:flex-start;border-bottom-left-radius:4px}.msg-time{display:block;color:var(--muted);font-size:.65rem;text-align:right;margin-top:6px}.msg.read .msg-time:after{content:'  ✓✓';color:var(--accent)}.msg-tools{display:flex;gap:4px;justify-content:flex-end;margin-top:7px}.msg-tools button,.reaction-chip{border:1px solid var(--line);border-radius:99px;background:#0002;padding:3px 7px;color:var(--text);cursor:pointer}.reaction-bar{display:none;gap:4px;flex-wrap:wrap}.msg:hover .reaction-bar,.msg:focus-within .reaction-bar{display:flex}.reaction-chip{font-size:.8rem}.msg-delete{color:var(--danger)!important}.msg-img{display:block;max-width:min(350px,100%);max-height:300px;border-radius:10px}.file-link{color:var(--accent)}.input-zone{display:flex;align-items:center;gap:8px;padding:12px 15px calc(12px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:#090d17ed;backdrop-filter:blur(16px);flex:none}.input-zone.hidden{display:none}.input{flex:1;min-width:0;padding:12px;border:1px solid var(--line);border-radius:12px;background:#080d18;color:var(--text)}.send{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#08120e;border:0;font-weight:700}.composer-options{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:.74rem;white-space:nowrap}.composer-options input{accent-color:var(--accent)}.toolbar{display:flex;gap:8px;align-items:center;padding:9px 16px;border-bottom:1px solid var(--line)}.chat-search{flex:1;padding:8px 11px}.empty{margin:auto;text-align:center;padding:20px;color:var(--muted);line-height:1.7}.hidden{display:none!important}.modal-overlay{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:#02050bcc;backdrop-filter:blur(9px)}.modal{width:min(480px,100%);max-height:90dvh;overflow:auto;padding:24px;border-radius:20px}.modal h2{margin:0 0 7px;font:600 1.35rem 'Space Grotesk'}.modal p{color:var(--muted);line-height:1.5}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:12px 0;border-top:1px solid var(--line);color:var(--muted)}.setting-row select{padding:8px;background:#101728;color:var(--text);border:1px solid var(--line);border-radius:9px}.swatches{display:flex;gap:7px}.swatch{width:25px;height:25px;border:0;border-radius:50%;cursor:pointer}.swatch[data-value=glass]{background:linear-gradient(135deg,#83ecc4,#91a9ff)}.swatch[data-value=aurora]{background:linear-gradient(135deg,#65fbd2,#b59aff)}.swatch[data-value=midnight]{background:linear-gradient(135deg,#c2a8ff,#75bcff)}.swatch[data-value=rose]{background:linear-gradient(135deg,#ffb4d2,#c6a0ff)}.danger-btn{color:var(--danger)}.once-overlay{position:fixed;inset:0;z-index:35;display:grid;place-items:center;background:#050812f5;padding:20px}.once-card{width:min(600px,100%);max-height:90dvh;overflow:auto;padding:22px;border:1px solid var(--line);border-radius:20px;background:#111827}.once-body{min-height:100px;display:grid;place-items:center;overflow-wrap:anywhere}.once-body img{max-width:100%;max-height:65dvh}.toast{position:fixed;z-index:50;bottom:22px;left:50%;transform:translate(-50%,12px);opacity:0;background:#182136;border:1px solid var(--line);padding:11px 16px;border-radius:12px;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}body[data-theme=aurora]{--bg:#071218;--accent:#65fbd2;--accent2:#b59aff}body[data-theme=midnight]{--bg:#080a13;--accent:#c2a8ff;--accent2:#75bcff}body[data-theme=rose]{--bg:#140b15;--accent:#ffb4d2;--accent2:#c6a0ff}body[data-theme=light]{color-scheme:light;--bg:#edf2f8;--text:#1d2634;--muted:#5e6b7d;--line:#182b471f;--surface:#ffffffd9;background:#edf2f8}.msg-match{outline:2px solid var(--accent)}body[data-density=compact] .messages{gap:6px;padding-top:12px;padding-bottom:12px}body[data-density=compact] .msg{padding:8px 10px}body[data-font-size=large]{font-size:16px}body[data-motion=off] *,body[data-motion=off] *:before,body[data-motion=off] *:after{animation:none!important;transition:none!important}@media(max-width:850px){.app{grid-template-columns:270px minmax(0,1fr);padding:10px;gap:10px}.key-label{display:none}.settings-trigger .button-label{display:none}.composer-options{font-size:.66rem}}@media(max-width:650px){.app{display:block;padding:0}.sidebar{display:none;position:fixed;z-index:15;inset:8px auto 8px 8px;width:min(330px,calc(100vw - 16px));background:#101827f5}.sidebar.active{display:flex}.chat{height:100dvh;border:0;border-radius:0}.mobile-menu{display:inline-block}.chat-head{padding:9px}.head-actions{gap:4px}.key-input{width:90px;padding:8px}.messages{padding:14px}.msg{max-width:90%}.input-zone{gap:5px;padding:9px 8px calc(9px + env(safe-area-inset-bottom))}.composer-options{gap:4px}.once-card{padding:14px}}@media(min-width:651px){.mobile-menu{display:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important;transition:none!important}}
</style></head><body><div class="app"><aside class="sidebar glass" id="sidebar"><div class="side-head"><a href="index.php" class="brand"><img src="sdpGhostlink.png" alt=""><span>GhostLink</span></a><p class="subline">Private conversations, made personal.</p><input id="searchUser" class="search" type="search" placeholder="Search people…" aria-label="Search people"></div><div class="list-label">Contacts</div><div id="userList" class="user-list"><div class="empty">Finding people…</div></div><div class="side-foot"><button class="side-link" onclick="showProfile()">Profile</button><button class="side-link" onclick="showSettings()">Settings</button><a class="side-link" href="index.php?page=usage">Guide</a><a class="side-link abort" href="logout.php">Sign out</a></div></aside><main class="chat glass"><header class="chat-head"><div class="head-left"><button class="icon-btn mobile-menu" onclick="toggleSidebar()" aria-label="Contacts">☰</button><div><div class="target" id="chatTitle">Choose someone to chat</div><div class="target-sub" id="chatSubtitle">Select a contact to begin</div></div></div><div class="head-actions"><label class="key-label">Shared key</label><input id="secretKey" class="key-input" type="password" placeholder="Shared key" autocomplete="off" aria-label="Shared encryption key"><button class="icon-btn" type="button" onclick="showSettings()" title="Settings">⚙</button><button class="icon-btn" type="button" onclick="showProfile()" title="Profile">☺</button></div></header><div class="toolbar"><input id="chatSearch" class="chat-search" type="search" placeholder="Search in this chat…" aria-label="Search messages"><button id="clearChat" class="tool-btn danger-btn" type="button" title="Delete all messages in this conversation">Clear chat</button></div><section class="messages" id="msgBox" aria-live="polite"><div class="empty">Select a person to start a conversation.</div></section><form class="input-zone hidden" id="inputZone"><button type="button" class="attach" id="attachButton" title="Attach file">＋</button><input id="msgInput" class="input" placeholder="Write a message…" autocomplete="off"><label class="composer-options" title="This message and attachment can be opened once"><input type="checkbox" id="viewOnce">View once</label><button class="send" id="sendButton">Send ↗</button></form></main></div><input id="fileInput" type="file" hidden><div id="toast" class="toast" role="status" aria-live="polite"></div>
<div id="settingsModal" class="modal-overlay hidden"><section class="modal glass" role="dialog" aria-modal="true"><h2>Advanced settings</h2><p>Personalise this device's chat experience.</p><div class="setting-row"><span>Theme</span><div class="swatches"><button class="swatch" data-theme-choice="glass" aria-label="Glass theme"></button><button class="swatch" data-theme-choice="aurora" aria-label="Aurora theme"></button><button class="swatch" data-theme-choice="midnight" aria-label="Midnight theme"></button><button class="swatch" data-theme-choice="rose" aria-label="Rose theme"></button><button class="swatch" data-theme-choice="light" aria-label="Light theme" style="background:linear-gradient(135deg,#fff,#8ca9ff)"></button></div></div><div class="setting-row"><span>Message spacing</span><select id="densitySetting"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><div class="setting-row"><span>Text size</span><select id="fontSetting"><option value="normal">Normal</option><option value="large">Large</option></select></div><div class="setting-row"><span>Motion effects</span><input id="motionSetting" type="checkbox" checked></div><div class="setting-row"><span>Notification sound</span><input id="soundSetting" type="checkbox" checked></div><div class="setting-row"><span>Confirm before clearing chat</span><input id="confirmSetting" type="checkbox" checked></div><div style="text-align:right;margin-top:14px"><button class="send" type="button" onclick="closeSettings()">Done</button></div></section></div>
<div id="profileModal" class="modal-overlay hidden"><section class="modal glass" role="dialog" aria-modal="true"><h2>Your profile</h2><p>Edit the details shown to other people.</p><input id="editBio" placeholder="Short bio" maxlength="255"><input id="editPhone" placeholder="Phone number"><div style="text-align:right;margin-top:14px"><button class="send" type="button" onclick="saveProfile()">Save</button></div></section></div><div id="onceOverlay" class="once-overlay hidden"><section class="once-card"><h2>View once</h2><p id="onceCountdown">This content will be removed when you close it.</p><div id="onceBody" class="once-body"></div><div style="text-align:right;margin-top:15px"><button class="send" type="button" id="closeOnce">Close & destroy</button></div></section></div>
<script>
'use strict';let currentTargetId=null,currentTargetName='',poll=null,requestVersion=0,knownIds=new Set(),pendingAttachment='',onceTimer=null,toastTimer=null;const $=id=>document.getElementById(id);const REACTIONS=['👍','❤️','😂','😮','😢','🎉'];
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function authCheck(text){if(text.trim()==='ACCESS DENIED'){location.href='index.php?page=login&error=Session%20Expired';return false}return true}
async function post(fields){const f=new FormData();for(const [k,v]of Object.entries(fields))f.append(k,v);const r=await fetch('engine.php',{method:'POST',body:f,credentials:'same-origin'});return r.text()}
function toggleSidebar(){$('sidebar').classList.toggle('active')}
function applySettings(p){document.body.dataset.theme=p.theme;document.body.dataset.density=p.density;document.body.dataset.fontSize=p.font;document.body.dataset.motion=p.motion?'on':'off';$('densitySetting').value=p.density;$('fontSetting').value=p.font;$('motionSetting').checked=p.motion;$('soundSetting').checked=p.sound;$('confirmSetting').checked=p.confirm;document.querySelector('meta[name=theme-color]').content=p.theme==='light'?'#edf2f8':p.theme==='aurora'?'#071218':p.theme==='rose'?'#140b15':p.theme==='midnight'?'#080a13':'#090d17'}
function getSettings(){return{theme:document.body.dataset.theme||'glass',density:$('densitySetting').value,font:$('fontSetting').value,motion:$('motionSetting').checked,sound:$('soundSetting').checked,confirm:$('confirmSetting').checked}}
function saveSettings(){const p=getSettings();try{localStorage.setItem('ghostlink-advanced-settings',JSON.stringify(p))}catch(e){}applySettings(p)}
function loadSettings(){let p={};try{p=JSON.parse(localStorage.getItem('ghostlink-advanced-settings')||'{}')}catch(e){}applySettings({...{theme:'glass',density:'comfortable',font:'normal',motion:true,sound:true,confirm:true},...p})}
window.showSettings=()=>{$('settingsModal').classList.remove('hidden')};window.closeSettings=()=> $('settingsModal').classList.add('hidden');document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{document.body.dataset.theme=b.dataset.themeChoice;saveSettings()});['densitySetting','fontSetting','motionSetting','soundSetting','confirmSetting'].forEach(id=>$(id).addEventListener('change',saveSettings));
function renderContacts(html){const list=$('userList');if(list.dataset.raw===html)return;list.dataset.raw=html;list.innerHTML=html;list.querySelectorAll('.user-card').forEach(card=>{if(card.dataset.userId===currentTargetId)card.classList.add('active');card.onclick=()=>openChat(card.dataset.userId,card.dataset.username)})}
async function fetchUsers(){try{const html=await post({mode:'get_users',search:$('searchUser').value});if(authCheck(html))renderContacts(html)}catch(e){}}
function openChat(id,name){currentTargetId=String(id);currentTargetName=name||'Conversation';$('chatTitle').textContent=currentTargetName;$('chatSubtitle').textContent='🔒 Messages are encrypted in your browser';$('inputZone').classList.remove('hidden');$('sidebar').classList.remove('active');knownIds=new Set();document.querySelectorAll('.user-card').forEach(c=>c.classList.toggle('active',c.dataset.userId===currentTargetId));$('msgBox').innerHTML='<div class="empty">Loading conversation…</div>';if(poll)clearInterval(poll);const version=++requestVersion;fetchMessages(version);poll=setInterval(()=>fetchMessages(version),2500)}
function appendContent(el,text){if(text.startsWith('FILE:')){const path=text.slice(5).trim();if(!/^uploads\/[\w.-]+$/.test(path)){el.append(document.createTextNode('Attachment unavailable'));return}const ext=path.split('.').pop().toLowerCase();if(['jpg','jpeg','png','gif','webp'].includes(ext)){const img=document.createElement('img');img.src=path;img.alt='Shared image';img.className='msg-img';img.loading='lazy';el.append(img)}else{const a=document.createElement('a');a.href=path;a.target='_blank';a.rel='noopener noreferrer';a.className='file-link';a.textContent='↗ Open '+ext.toUpperCase()+' file';el.append(a)}return}el.append(document.createTextNode(text))}
function reactionControls(id,container){const bar=document.createElement('div');bar.className='msg-tools reaction-bar';REACTIONS.forEach(emoji=>{const b=document.createElement('button');b.type='button';b.className='reaction-chip';b.textContent=emoji;b.title='React '+emoji;b.onclick=async()=>{const r=await post({mode:'toggle_reaction',msg_id:id,reaction:emoji});if(r.trim()==='ok')fetchMessages(requestVersion)};bar.append(b)});container.append(bar)}
function renderReactions(message,json){let old=message.querySelector('.reaction-summary');if(old)old.remove();try{const values=JSON.parse(json||'[]');if(!values.length)return;const wrap=document.createElement('div');wrap.className='msg-tools reaction-summary';values.forEach(x=>{const b=document.createElement('button');b.type='button';b.className='reaction-chip';b.textContent=x.emoji+' '+x.count;wrap.append(b)});message.append(wrap)}catch(e){}}
function showMessageMenu(message,id,mine){if(mine){const b=document.createElement('button');b.className='reaction-chip msg-delete';b.type='button';b.textContent='Delete';b.onclick=()=>deleteMessage(id);message.append(b)}}
async function fetchMessages(version=requestVersion){if(!currentTargetId||version!==requestVersion)return;try{const html=await post({mode:'get_msgs',target:currentTargetId});if(version!==requestVersion||!authCheck(html))return;const temp=document.createElement('div');temp.innerHTML=html;const rows=[...temp.querySelectorAll('.msg')],box=$('msgBox'),nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<100,next=new Set();for(const row of rows){const id=row.id;if(!id)continue;next.add(id);const once=row.dataset.viewOnce==='1';let node=document.getElementById(id);const signature=(row.dataset.enc||'')+'|'+row.dataset.reactions+'|'+row.className;if(node&&node.dataset.signature===signature)continue;if(!node){node=document.createElement('article');node.id=id;node.className='msg '+(row.classList.contains('sent')?'sent':'received');box.append(node)}else{node.replaceChildren();node.className='msg '+(row.classList.contains('sent')?'sent':'received')}node.dataset.signature=signature;node.dataset.once=once?'1':'0';node.dataset.encrypted=row.dataset.enc||'';const idNum=id.slice(4),mine=row.classList.contains('sent');if(once&&!mine){const open=document.createElement('button');open.type='button';open.className='send';open.textContent='Open view-once message';open.onclick=()=>openOnce(idNum,node);node.append(open);const warning=document.createElement('small');warning.className='msg-time';warning.textContent='Opens once, then is removed from the server.';node.append(warning)}else{let text='';if($('secretKey').value&&typeof CryptoJS!=='undefined'){try{text=CryptoJS.AES.decrypt(row.dataset.enc||'',$('secretKey').value).toString(CryptoJS.enc.Utf8)}catch(e){}}if(text)appendContent(node,text);else node.append(document.createTextNode($('secretKey').value?'Unable to decrypt. Check the shared key.':'Enter your shared key to read this message.'));if(once&&mine){const tag=document.createElement('small');tag.className='msg-time';tag.textContent='View once · waiting to be opened';node.append(tag)}}if(row.dataset.time&&!once){const time=document.createElement('small');time.className='msg-time';time.textContent=row.dataset.time;node.append(time)}reactionControls(idNum,node);renderReactions(node,row.dataset.reactions);showMessageMenu(node,idNum,mine)}for(const old of [...box.querySelectorAll('.msg')])if(!next.has(old.id))old.remove();if(!rows.length)box.innerHTML='<div class="empty">No messages yet. Send the first one.</div>';else{box.querySelector('.empty')?.remove();if(nearBottom)box.scrollTop=box.scrollHeight}knownIds=next}catch(e){}}
async function sendMessage(){const text=$('msgInput').value,key=$('secretKey').value;if(!currentTargetId)return toast('Choose a contact first.');if(!text.trim())return;if(!key.trim())return toast('Enter your shared key first.');if(typeof CryptoJS==='undefined')return toast('Encryption library unavailable.');const input=$('msgInput'),btn=$('sendButton');btn.disabled=true;try{const msg=CryptoJS.AES.encrypt(text,key).toString(),response=await post({mode:'send_msg',target:currentTargetId,msg,view_once:$('viewOnce').checked?1:0,attachment_path:pendingAttachment});if(!authCheck(response))return;if(response.trim()==='sent'){input.value='';pendingAttachment='';$('viewOnce').checked=false;await fetchMessages()}else toast(response)}catch(e){toast('Message could not be sent.')}finally{btn.disabled=false;input.focus()}}
async function uploadFile(){const f=$('fileInput');if(!f.files.length)return;const file=f.files[0];if(file.size>25000000){f.value='';return toast('File exceeds the 25 MB limit.')}if(!currentTargetId||!$('secretKey').value.trim()){f.value='';return toast('Choose a chat and enter your shared key first.')}try{const data=new FormData();data.append('file',file);const response=await fetch('upload.php',{method:'POST',body:data,credentials:'same-origin'});const path=(await response.text()).trim();if(path.startsWith('error:'))return toast(path);pendingAttachment=path;$('msgInput').value='FILE:'+path;await sendMessage()}catch(e){toast('Upload failed.')}finally{f.value='';pendingAttachment='';$('msgInput').value=''}}
async function openOnce(id,node){try{const raw=await post({mode:'open_view_once',msg_id:id});if(!authCheck(raw))return;const data=JSON.parse(raw);if(data.error)throw new Error(data.error);let content='';try{content=CryptoJS.AES.decrypt(data.message,$('secretKey').value).toString(CryptoJS.enc.Utf8)}catch(e){}if(!content)throw new Error('Unable to decrypt. Check the shared key.');$('onceBody').replaceChildren();const text=content.startsWith('FILE:')?content.slice(5).trim():'';if(text){if(!/^uploads\/[\w.-]+$/.test(text))throw new Error('Attachment unavailable');const ext=text.split('.').pop().toLowerCase();if(['jpg','jpeg','png','gif','webp'].includes(ext)){const img=document.createElement('img');img.src=text;img.alt='View-once image';$('onceBody').append(img)}else{const a=document.createElement('a');a.href=text;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open attachment';$('onceBody').append(a)}}else $('onceBody').textContent=content;$('onceOverlay').classList.remove('hidden');let seconds=15;$('onceCountdown').textContent='This content closes and is destroyed in '+seconds+' seconds.';clearInterval(onceTimer);onceTimer=setInterval(()=>{seconds--;$('onceCountdown').textContent=seconds>0?'This content closes and is destroyed in '+seconds+' seconds.':'Removing from the server…';if(seconds<=0)closeOnce(id)},1000);$('closeOnce').onclick=()=>closeOnce(id)}catch(e){toast(e.message||'This view-once message is unavailable.');fetchMessages()}}
let finishingOnce=false;async function closeOnce(id){if(finishingOnce)return;finishingOnce=true;clearInterval(onceTimer);$('onceOverlay').classList.add('hidden');$('onceBody').replaceChildren();try{await post({mode:'finish_view_once',msg_id:id})}finally{finishingOnce=false;fetchMessages()}}
async function deleteMessage(id){if(!confirm('Delete this message for everyone?'))return;try{const r=await post({mode:'delete_msg',msg_id:id});if(r.trim()==='deleted'){document.getElementById('msg_'+id)?.remove();knownIds.delete('msg_'+id);toast('Message deleted for everyone.')}}catch(e){toast('Could not delete message.')}}
$('clearChat').onclick=async()=>{if(!currentTargetId)return toast('Select a conversation first.');if(getSettings().confirm&&!confirm('Clear this entire conversation for both people? Messages and attachments will be deleted permanently.'))return;try{const r=await post({mode:'clear_chat',target:currentTargetId});if(r.startsWith('cleared:')){knownIds.clear();$('msgBox').innerHTML='<div class="empty">Conversation cleared.</div>';toast('Conversation deleted for both people.')}}catch(e){toast('Could not clear conversation.')}};
$('chatSearch').addEventListener('input',()=>{const q=$('chatSearch').value.toLocaleLowerCase();document.querySelectorAll('#msgBox .msg').forEach(m=>{m.classList.remove('msg-match');if(!q)return;let text=m.textContent.toLocaleLowerCase();try{const plain=CryptoJS.AES.decrypt(m.dataset.encrypted||'',$('secretKey').value).toString(CryptoJS.enc.Utf8);text+=' '+plain.toLocaleLowerCase()}catch(e){}if(text.includes(q))m.classList.add('msg-match')})});
window.showProfile=async()=>{$('profileModal').classList.remove('hidden');try{const r=await post({mode:'get_my_profile'});if(authCheck(r)){const p=JSON.parse(r);$('editBio').value=p.bio||'';$('editPhone').value=p.phone||''}}catch(e){toast('Profile load failed.')}};window.saveProfile=async()=>{try{const r=await post({mode:'update_profile',bio:$('editBio').value,phone:$('editPhone').value});if(r.trim()==='updated'){$('profileModal').classList.add('hidden');toast('Profile saved.');fetchUsers()}}catch(e){toast('Profile save failed.')}};
$('inputZone').addEventListener('submit',e=>{e.preventDefault();sendMessage()});$('attachButton').onclick=()=>$('fileInput').click();$('fileInput').addEventListener('change',uploadFile);$('searchUser').addEventListener('input',fetchUsers);$('secretKey').addEventListener('input',()=>currentTargetId&&fetchMessages());document.querySelectorAll('.modal-overlay').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.add('hidden')}));window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.modal-overlay').forEach(m=>m.classList.add('hidden'));$('sidebar').classList.remove('active');if(!$('onceOverlay').classList.contains('hidden')){const id=document.querySelector('#msgBox .msg[data-once="1"]')?.id.slice(4);if(id)closeOnce(id)}}});loadSettings();fetchUsers();setInterval(fetchUsers,7000);
</script></body></html>
